local GlassColorantMaker = {}
local PRODUCTS = {
    iron_glass_colorant = { name = "Železno barvilo za steklo", ironCost = 2, woodCost = 2, leatherCost = 1, time = 5, cost = 170, prestige = 4, happiness = 2, description = "Železno barvilo za barvno steklo." },
    bronze_glass_colorant = { name = "Bronasto barvilo za steklo", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 410, prestige = 6, happiness = 3, description = "Bronasto barvilo za živo barvno steklo." },
    silver_glass_colorant = { name = "Srebrno barvilo za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 990, prestige = 11, happiness = 4, description = "Srebrno barvilo za plemiško barvno steklo." },
    gilded_glass_colorant = { name = "Pozlačeno barvilo za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2130, prestige = 20, happiness = 5, description = "Pozlačeno barvilo za dvorno barvno steklo." },
    jewel_set_glass_colorant = { name = "Draguljasto barvilo za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4600, prestige = 36, happiness = 7, description = "Draguljasto barvilo za kraljevsko barvno steklo." },
    royal_sovereign_glass_colorant = { name = "Kraljevski suvereno barvilo za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 9800, prestige = 69, happiness = 13, description = "Suvereno barvilo z biseri za krono." },
}
local BUILDINGS = {
    glasscolorant_workshop = { name = "Barvilna delavnica", cost = { gold = 345, wood = 180, stone = 135, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glasscolorant_house = { name = "Barvilna hiša", cost = { gold = 1230, wood = 365, stone = 275, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_glasscolorant_atelier = { name = "Mojstrski barvilni atelje", cost = { gold = 3080, wood = 425, stone = 525, silver = 36, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_glasscolorant_palace = { name = "Suverena barvilna palača", cost = { gold = 13150, wood = 650, stone = 835, gold = 84, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
GlassColorantMaker.ironStock = 12; GlassColorantMaker.bronzeStock = 10; GlassColorantMaker.woodStock = 14; GlassColorantMaker.leatherStock = 10; GlassColorantMaker.silverStock = 10; GlassColorantMaker.goldStock = 6; GlassColorantMaker.jewelStock = 4; GlassColorantMaker.pearlStock = 4
GlassColorantMaker.productStock = {}; GlassColorantMaker.buildings = {}; GlassColorantMaker.maker = nil; GlassColorantMaker.activeMaking = {}; GlassColorantMaker.totalProducts = 0; GlassColorantMaker.dayTimer = 0
function GlassColorantMaker.init() GlassColorantMaker.ironStock=12; GlassColorantMaker.bronzeStock=10; GlassColorantMaker.woodStock=14; GlassColorantMaker.leatherStock=10; GlassColorantMaker.silverStock=10; GlassColorantMaker.goldStock=6; GlassColorantMaker.jewelStock=4; GlassColorantMaker.pearlStock=4; GlassColorantMaker.productStock={}; GlassColorantMaker.buildings={}; GlassColorantMaker.maker=nil; GlassColorantMaker.activeMaking={}; GlassColorantMaker.totalProducts=0; GlassColorantMaker.dayTimer=0; print("[GlassColorantMaker] Royal Glass Colorant Maker System initialized (6 products, 4 buildings)") end
function GlassColorantMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassColorantMaker.maker={name=n or ("Barvar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barvar najet: %s (spretnost: %d)",GlassColorantMaker.maker.name,s),"success") end; return true end
function GlassColorantMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassColorantMaker.build(id) local ok,e=GlassColorantMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassColorantMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassColorantMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassColorantMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassColorantMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassColorantMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassColorantMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassColorantMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassColorantMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassColorantMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassColorantMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassColorantMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassColorantMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassColorantMaker.buildings==0 then return false,"Potrebna barvilna delavnica" end; if not GlassColorantMaker.maker then return false,"Potreben barvar" end; return true end
function GlassColorantMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassColorantMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassColorantMaker.ironStock=GlassColorantMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassColorantMaker.bronzeStock=GlassColorantMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassColorantMaker.woodStock=GlassColorantMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassColorantMaker.leatherStock=GlassColorantMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassColorantMaker.silverStock=GlassColorantMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassColorantMaker.goldStock=GlassColorantMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassColorantMaker.jewelStock=GlassColorantMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassColorantMaker.pearlStock=GlassColorantMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassColorantMaker.maker then t=math.max(1,t-math.floor(GlassColorantMaker.maker.skill/13)) end; table.insert(GlassColorantMaker.activeMaking,{id="glasscolorant_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassColorantMaker.completeMaking(m) local q=1.0+(GlassColorantMaker.getQualityBonus()/100); if GlassColorantMaker.maker then q=q+(GlassColorantMaker.maker.skill/140) end; q=math.min(2.5,q); GlassColorantMaker.productStock[m.productType]=(GlassColorantMaker.productStock[m.productType] or 0)+m.quantity; GlassColorantMaker.totalProducts=GlassColorantMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassColorantMaker.maker then GlassColorantMaker.maker.itemsMade=GlassColorantMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassColorantMaker.maker.skill=math.min(100,GlassColorantMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barvilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscolorant.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassColorantMaker.update(dt) if not _G.state then return end; GlassColorantMaker.dayTimer=GlassColorantMaker.dayTimer+dt; if GlassColorantMaker.dayTimer>=30 then GlassColorantMaker.dayTimer=0; for i=#GlassColorantMaker.activeMaking,1,-1 do local m=GlassColorantMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassColorantMaker.completeMaking(m); table.remove(GlassColorantMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassColorantMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassColorantMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassColorantMaker.getStats() return {ironStock=GlassColorantMaker.ironStock,bronzeStock=GlassColorantMaker.bronzeStock,woodStock=GlassColorantMaker.woodStock,leatherStock=GlassColorantMaker.leatherStock,silverStock=GlassColorantMaker.silverStock,goldStock=GlassColorantMaker.goldStock,jewelStock=GlassColorantMaker.jewelStock,pearlStock=GlassColorantMaker.pearlStock,productStock=GlassColorantMaker.productStock,numBuildings=#GlassColorantMaker.buildings,hasMaker=GlassColorantMaker.maker~=nil,makerName=GlassColorantMaker.maker and GlassColorantMaker.maker.name or "—",makerSkill=GlassColorantMaker.maker and GlassColorantMaker.maker.skill or 0,activeMaking=#GlassColorantMaker.activeMaking,totalProducts=GlassColorantMaker.totalProducts} end
return GlassColorantMaker
